import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Form, 
  Button, Alert, Tabs, Tab 
} from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useNotification } from '../contexts/NotificationContext';

const AuthPage = () => {
  const navigate = useNavigate();
  const { login, register, isAuthenticated } = useAuth();
  const { showNotification, showError, showSuccess } = useNotification();
  
  const [activeTab, setActiveTab] = useState('login');
  const [loading, setLoading] = useState(false);
  
  // Login form state
  const [loginData, setLoginData] = useState({
    email: '',
    password: ''
  });
  
  // Register form state
  const [registerData, setRegisterData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: ''
  });

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/dashboard');
    }
  }, [isAuthenticated, navigate]);

  const handleLoginChange = (e) => {
    const { name, value } = e.target;
    setLoginData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleRegisterChange = (e) => {
    const { name, value } = e.target;
    setRegisterData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    
    if (!loginData.email || !loginData.password) {
      showError('Email dan password harus diisi');
      return;
    }

    setLoading(true);
    try {
      const result = await login(loginData.email, loginData.password);
      
      if (result.success) {
        showSuccess('Login berhasil!');
        navigate('/dashboard');
      } else {
        showError(result.message || 'Login gagal');
      }
    } catch (error) {
      console.error('Login error:', error);
      showError('Terjadi kesalahan saat login');
    } finally {
      setLoading(false);
    }
  };

  const handleRegisterSubmit = async (e) => {
    e.preventDefault();
    
    // Validation
    if (!registerData.name || !registerData.email || !registerData.password) {
      showError('Semua field harus diisi');
      return;
    }
    
    if (registerData.password !== registerData.confirmPassword) {
      showError('Password dan konfirmasi password tidak sama');
      return;
    }
    
    if (registerData.password.length < 6) {
      showError('Password minimal 6 karakter');
      return;
    }

    setLoading(true);
    try {
      const result = await register(
        registerData.name,
        registerData.email,
        registerData.password
      );
      
      if (result.success) {
        showSuccess('Registrasi berhasil!');
        navigate('/dashboard');
      } else {
        showError(result.message || 'Registrasi gagal');
      }
    } catch (error) {
      console.error('Register error:', error);
      showError('Terjadi kesalahan saat registrasi');
    } finally {
      setLoading(false);
    }
  };

  const handleDemoLogin = () => {
    setLoginData({
      email: 'demo@spse.com',
      password: 'demo123'
    });
    // Ganti showInfo dengan showNotification atau showSuccess
    showNotification('Gunakan demo@spse.com / demo123 untuk login demo', 'info');
  };

  return (
    <Container className="py-5">
      <Row className="justify-content-center">
        <Col md={8} lg={6}>
          <Card className="shadow">
            <Card.Header className="bg-primary text-white text-center">
              <h4 className="mb-0">
                <i className="fas fa-user-circle me-2"></i>
                SPSE Scraper - Authentication
              </h4>
            </Card.Header>
            
            <Card.Body>
              <Tabs
                activeKey={activeTab}
                onSelect={(k) => setActiveTab(k)}
                className="mb-4"
              >
                <Tab eventKey="login" title="Login">
                  <Form onSubmit={handleLoginSubmit}>
                    <Form.Group className="mb-3">
                      <Form.Label>Email</Form.Label>
                      <Form.Control
                        type="email"
                        name="email"
                        placeholder="Masukkan email"
                        value={loginData.email}
                        onChange={handleLoginChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <Form.Group className="mb-3">
                      <Form.Label>Password</Form.Label>
                      <Form.Control
                        type="password"
                        name="password"
                        placeholder="Masukkan password"
                        value={loginData.password}
                        onChange={handleLoginChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <div className="d-grid gap-2">
                      <Button
                        type="submit"
                        variant="primary"
                        disabled={loading}
                      >
                        {loading ? (
                          <>
                            <span className="spinner-border spinner-border-sm me-2"></span>
                            Processing...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-sign-in-alt me-2"></i>
                            Login
                          </>
                        )}
                      </Button>
                      
                      <Button
                        variant="outline-secondary"
                        onClick={handleDemoLogin}
                        disabled={loading}
                      >
                        <i className="fas fa-magic me-2"></i>
                        Gunakan Akun Demo
                      </Button>
                    </div>
                  </Form>
                </Tab>
                
                <Tab eventKey="register" title="Register">
                  <Form onSubmit={handleRegisterSubmit}>
                    <Form.Group className="mb-3">
                      <Form.Label>Nama Lengkap</Form.Label>
                      <Form.Control
                        type="text"
                        name="name"
                        placeholder="Masukkan nama lengkap"
                        value={registerData.name}
                        onChange={handleRegisterChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <Form.Group className="mb-3">
                      <Form.Label>Email</Form.Label>
                      <Form.Control
                        type="email"
                        name="email"
                        placeholder="Masukkan email"
                        value={registerData.email}
                        onChange={handleRegisterChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <Form.Group className="mb-3">
                      <Form.Label>Password</Form.Label>
                      <Form.Control
                        type="password"
                        name="password"
                        placeholder="Minimal 6 karakter"
                        value={registerData.password}
                        onChange={handleRegisterChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <Form.Group className="mb-4">
                      <Form.Label>Konfirmasi Password</Form.Label>
                      <Form.Control
                        type="password"
                        name="confirmPassword"
                        placeholder="Ulangi password"
                        value={registerData.confirmPassword}
                        onChange={handleRegisterChange}
                        required
                        disabled={loading}
                      />
                    </Form.Group>
                    
                    <div className="d-grid">
                      <Button
                        type="submit"
                        variant="success"
                        disabled={loading}
                      >
                        {loading ? (
                          <>
                            <span className="spinner-border spinner-border-sm me-2"></span>
                            Processing...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-user-plus me-2"></i>
                            Register
                          </>
                        )}
                      </Button>
                    </div>
                  </Form>
                </Tab>
              </Tabs>
              
              {/* Demo Info */}
              <Alert variant="info" className="mt-4">
                <h6>
                  <i className="fas fa-info-circle me-2"></i>
                  Informasi Akun Demo
                </h6>
                <p className="mb-2">
                  <strong>Email:</strong> demo@spse.com
                </p>
                <p className="mb-0">
                  <strong>Password:</strong> demo123
                </p>
                <Button
                  variant="outline-info"
                  size="sm"
                  className="mt-2"
                  onClick={handleDemoLogin}
                >
                  <i className="fas fa-magic me-1"></i>
                  Auto-fill Demo Login
                </Button>
              </Alert>
              
              {/* Features */}
              <div className="mt-4">
                <h6 className="text-muted mb-3">
                  <i className="fas fa-star me-2 text-warning"></i>
                  Fitur Untuk User Terdaftar:
                </h6>
                <ul className="list-unstyled">
                  <li className="mb-2">
                    <i className="fas fa-check text-success me-2"></i>
                    Simpan pencarian favorit
                  </li>
                  <li className="mb-2">
                    <i className="fas fa-check text-success me-2"></i>
                    Dashboard analytics
                  </li>
                  <li className="mb-2">
                    <i className="fas fa-check text-success me-2"></i>
                    Riwayat pencarian
                  </li>
                  <li>
                    <i className="fas fa-check text-success me-2"></i>
                    Notifikasi real-time
                  </li>
                </ul>
              </div>
            </Card.Body>
            
            <Card.Footer className="text-center text-muted">
              <small>
                SPSE Scraper v9.0 • Support 2023-2026 • 
                <a 
                  href="http://localhost:5000/health" 
                  target="_blank" 
                  rel="noreferrer"
                  className="ms-1"
                >
                  Cek Status Backend
                </a>
              </small>
            </Card.Footer>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default AuthPage;